partment_id":"57b1e81f-6b20-4900-87fb-82d49cd4a6ec","slot_1_target":"KU02DSCPES102TT","slot_2_target":"KU02DSCPES103TT","slot_3_target":"PESTT","slot_4_target":"PESTT","slot_5_target":"MDC","slot_6_target":"AEC"},{"id":"4f5ab90f-ad41-4f3f-9fb7-c1b91428c8a9","pathways":[{"id":"tt-pes-s4-1","name":"Default","slots":[{"name":"MAJOR 1","rule":"FIXED","slot":1,"target":"KU04DSCPES205TT"},{"name":"MAJOR 2","rule":"FIXED","slot":2,"target":"KU04DSCPES206TT"},{"name":"MAJOR 3","rule":"FIXED","slot":3,"target":"KU04DSCPES207TT"},{"name":"MAJOR 4","rule":"FIXED","slot":4,"target":"KU04DSCPES208TT"},{"name":"SEC","rule":"GLOBAL_BASKET","slot":5,"target":"SEC"},{"name":"VAC","rule":"GLOBAL_BASKET","slot":6,"target":"VAC"}]}],"semester":4,"max_credits":22,"min_credits":0,"slot_1_name":"MAJOR 1","slot_1_rule":"FIXED","slot_2_name":"MAJOR 2","slot_2_rule":"FIXED","slot_3_name":"MAJOR 3","slot_3_rule":"FIXED","slot_4_name":"MAJOR 4","slot_4_rule":"FIXED","slot_5_name":"SEC","slot_5_rule":"GLOBAL_BASKET","slot_6_name":"VAC","slot_6_rule":"GLOBAL_BASKET","department_id":"57b1e81f-6b20-4900-87fb-82d49cd4a6ec","slot_1_target":"KU04DSCPES205TT","slot_2_target":"KU04DSCPES206TT","slot_3_target":"KU04DSCPES207TT","slot_4_target":"KU04DSCPES208TT","slot_5_target":"SEC","slot_6_target":"VAC"},{"id":"c960d2de-3392-474c-add1-f391322524ad","pathways":[{"id":"tt-sbs-s2-1","name":"Default","slots":[{"name":"MAJOR 1","rule":"FIXED","slot":1,"target":"KU02DSCPSY102TT"},{"name":"MAJOR 2","rule":"FIXED","slot":2,"target":"KU02DSCPSY103TT"},{"name":"MINOR 1","rule":"EXCLUDE_DEPT","slot":3,"target":"SBSTT"},{"name":"MINOR 2","rule":"EXCLUDE_DEPT","slot":4,"target":"SBSTT"},{"name":"MDC","rule":"GLOBAL_BASKET","slot":5,"target":"MDC"},{"name":"AEC","rule":"GLOBAL_BASKET","slot":6,"target":"AEC"}]}],"semester":2,"max_credits":22,"min_credits":20,"slot_1_name":"MAJOR 1","slot_1_rule":"FIXED","slot_2_name":"MAJOR 2","slot_2_rule":"FIXED","slot_3_name":"MINOR 1","slot_3_rule":"EXCLUDE_DEPT","slot_4_name":"MINOR 2","slot_4_rule":"EXCLUDE_DEPT","slot_5_name":"MDC","slot_5_rule":"GLOBAL_BASKET","slot_6_name":"AEC","slot_6_rule":"GLOBAL_BASKET","department_id":"9d3e0366-5b7c-4fc4-8f7e-680967378927","slot_1_target":"KU02DSCPSY102TT","slot_2_target":"KU02DSCPSY103TT","slot_3_target":"SBSTT","slot_4_target":"SBSTT","slot_5_target":"MDC","slot_6_target":"AEC"},{"id":"02ca72f3-b454-4ad0-b031-76e8036e754b","pathways":[{"id":"tt-sbs-s4-1","name":"Default","slots":[{"name":"MAJOR 1","rule":"FIXED","slot":1,"target":"KU04DSCPSY205TT"},{"name":"MAJOR 2","rule":"FIXED","slot":2,"target":"KU04DSCPSY206TT"},{"name":"MAJOR 3","rule":"FIXED","slot":3,"target":"KU04DSCPSY207TT"},{"name":"MAJOR 4","rule":"FIXED","slot":4,"target":"KU04DSCPSY208TT"},{"name":"SEC","rule":"GLOBAL_BASKET","slot":5,"target":"SEC"},{"name":"VAC","rule":"GLOBAL_BASKET","slot":6,"target":"VAC"}]}],"semester":4,"max_credits":22,"min_credits":0,"slot_1_name":"MAJOR 1","slot_1_rule":"FIXED","slot_2_name":"MAJOR 2","slot_2_rule":"FIXED","slot_3_name":"MAJOR 3","slot_3_rule":"FIXED","slot_4_name":"MAJOR 4","slot_4_rule":"FIXED","slot_5_name":"SEC","slot_5_rule":"GLOBAL_BASKET","slot_6_name":"VAC","slot_6_rule":"GLOBAL_BASKET","department_id":"9d3e0366-5b7c-4fc4-8f7e-680967378927","slot_1_target":"KU04DSCPSY205TT","slot_2_target":"KU04DSCPSY206TT","slot_3_target":"KU04DSCPSY207TT","slot_4_target":"KU04DSCPSY208TT","slot_5_target":"SEC","slot_6_target":"VAC"}]}'::jsonb;
  campus uuid := 'b72074e2-468e-4218-afb6-0f08f14cfe8f';
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.campuses WHERE id = campus AND code = 'MANGATTT') THEN RAISE EXCEPTION 'Wrong test campus'; END IF;
  IF jsonb_array_length(payload->'courses') <> 61 OR jsonb_array_length(payload->'blueprints') <> 12 THEN RAISE EXCEPTION 'Wrong payload counts'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_populate_recordset(NULL::public.departments, payload->'departments') p LEFT JOIN public.departments d ON d.id = p.id WHERE d.id IS NULL OR to_jsonb(d) IS DISTINCT FROM to_jsonb(p) OR d.campus_id <> campus) THEN RAISE EXCEPTION 'Test department mapping changed'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_populate_recordset(NULL::public.courses, payload->'courses') p LEFT JOIN public.departments d ON d.id = p.department_id WHERE d.campus_id IS DISTINCT FROM campus OR p.course_code NOT LIKE '%TT' OR p.semester NOT IN (2,4)) THEN RAISE EXCEPTION 'Invalid course scope'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_populate_recordset(NULL::public.semester_blueprints, payload->'blueprints') p LEFT JOIN public.departments d ON d.id = p.department_id WHERE d.campus_id IS DISTINCT FROM campus OR p.semester NOT IN (2,4)) THEN RAISE EXCEPTION 'Invalid blueprint scope'; END IF;
  IF EXISTS (SELECT 1 FROM public.courses c JOIN public.departments d ON d.id = c.department_id WHERE d.campus_id = campus) OR EXISTS (SELECT 1 FROM public.semester_blueprints b JOIN public.departments d ON d.id = b.department_id WHERE d.campus_id = campus) THEN RAISE EXCEPTION 'Test academic records already exist; verify before any rerun'; END IF;
  IF EXISTS (SELECT 1 FROM public.courses c JOIN jsonb_populate_recordset(NULL::public.courses, payload->'courses') p ON c.id = p.id OR upper(trim(c.course_code)) = upper(trim(p.course_code))) OR EXISTS (SELECT 1 FROM public.semester_blueprints b JOIN jsonb_populate_recordset(NULL::public.semester_blueprints, payload->'blueprints') p ON b.id = p.id OR (b.department_id = p.department_id AND b.semester = p.semester)) THEN RAISE EXCEPTION 'Live academic ID/code collision'; END IF;
  IF (SELECT md5(coalesce(string_agg(to_jsonb(c)::text, '' ORDER BY c.id), '')) FROM public.courses c JOIN public.departments d ON d.id = c.department_id WHERE d.campus_id <> campus) <> 'd5d0504986b012995a47d1d93c6d1b83' THEN RAISE EXCEPTION 'Course catalogue changed after preflight'; END IF;
  IF (SELECT md5(coalesce(string_agg(to_jsonb(b)::text, '' ORDER BY b.id), '')) FROM public.semester_blueprints b JOIN public.departments d ON d.id = b.department_id WHERE d.campus_id <> campus) <> 'cd039a00fc0892b4744519a32615fcd8' THEN RAISE EXCEPTION 'Blueprint source changed after preflight'; END IF;
  IF (SELECT md5(coalesce(string_agg(to_jsonb(r)::text, '' ORDER BY id), '')) FROM public.course_prerequisite_rules r) <> 'cd8ac002528f3d2122c3ddca21ff7049' THEN RAISE EXCEPTION 'Prerequisite rules changed after preflight'; END IF;
  INSERT INTO public.courses ("id", "course_code", "title", "department_id", "semester", "credits", "category", "tag", "theory_hours_per_week", "practical_hours_per_week", "seat_limit", "prerequisite_course_ids", "academic_level") SELECT r."id", r."course_code", r."title", r."department_id", r."semester", r."credits", r."category", r."tag", r."theory_hours_per_week", r."practical_hours_per_week", r."seat_limit", r."prerequisite_course_ids", r."academic_level" FROM jsonb_populate_recordset(NULL::public.courses, payload->'courses') r;
  INSERT INTO public.semester_blueprints ("id", "department_id", "semester", "min_credits", "max_credits", "slot_1_rule", "slot_1_target", "slot_2_rule", "slot_2_target", "slot_3_rule", "slot_3_target", "slot_4_rule", "slot_4_target", "slot_5_rule", "slot_5_target", "slot_6_rule", "slot_6_target", "slot_1_name", "slot_2_name", "slot_3_name", "slot_4_name", "slot_5_name", "slot_6_name", "pathways") SELECT r."id", r."department_id", r."semester", r."min_credits", r."max_credits", r."slot_1_rule", r."slot_1_target", r."slot_2_rule", r."slot_2_target", r."slot_3_rule", r."slot_3_target", r."slot_4_rule", r."slot_4_target", r."slot_5_rule", r."slot_5_target", r."slot_6_rule", r."slot_6_target", r."slot_1_name", r."slot_2_name", r."slot_3_name", r."slot_4_name", r."slot_5_name", r."slot_6_name", r."pathways" FROM jsonb_populate_recordset(NULL::public.semester_blueprints, payload->'blueprints') r;
  IF (SELECT count(*) FROM public.courses c JOIN public.departments d ON d.id = c.department_id WHERE d.campus_id = campus) <> 61 OR (SELECT count(*) FROM public.semester_blueprints b JOIN public.departments d ON d.id = b.department_id WHERE d.campus_id = campus) <> 12 THEN RAISE EXCEPTION 'Unexpected inserted counts'; END IF;
END;
$academic$;
COMMIT;
SELECT 'ACADEMIC_COPY_COMMITTED' AS status;
